"""The audit trail: who did what to which entity."""
import json


def record(con, actor_id, action, entity, entity_id=None, **details):
    con.execute("INSERT INTO audit_events(actor_id, action, entity, entity_id, details) VALUES (?, ?, ?, ?, ?)",
                (actor_id, action, entity, entity_id, json.dumps(details, ensure_ascii=False)))


def events(con, entity, entity_id):
    return [dict(r) for r in con.execute(
        "SELECT * FROM audit_events WHERE entity = ? AND entity_id = ? ORDER BY id", (entity, entity_id))]

