import unittest

from app import db, projects, tasks, users


class ProjectsTest(unittest.TestCase):
    def setUp(self):
        self.con = db.connect()
        self.ann = users.create_user(self.con, "ann@example.com", "Ann")

    def test_create_and_list(self):
        projects.create_project(self.con, self.ann, "Alpha")
        self.assertEqual([p["name"] for p in projects.list_projects(self.con, self.ann)], ["Alpha"])

    def test_tasks_belong_to_project(self):
        pid = projects.create_project(self.con, self.ann, "Alpha")
        tasks.add_task(self.con, pid, "Write spec")
        self.assertEqual(len(tasks.list_tasks(self.con, pid)), 1)

    def test_delete_removes_from_list(self):
        pid = projects.create_project(self.con, self.ann, "Alpha")
        projects.delete_project(self.con, self.ann, pid)
        self.assertEqual(projects.list_projects(self.con, self.ann), [])


if __name__ == "__main__":
    unittest.main()
